// CurrencyCodes are the codes of the seeded currencies, the ones the fx rates
// job fetches.
func CurrencyCodes() []string {
	codes := make([]string, len(currSeed))
	for i, c := range currSeed {
		codes[i] = c.String
	}
	return codes
}
